mapper.select:
select
,
,
(select x.role from person x where x.deleted = 0 and (x.username = d.applicant or x.name = d.applicant) limit 1) as applicant_role,
(select x.role from person x where x.deleted = 0 and (x.username = d.approver or x.name = d.approver) limit 1) as approver_role


    d.deleted = 0
     and d.id= #{id}
     and d.deploy_no like concat('%', #{deployNo}, '%')
     and d.status= #{status}
     and d.app_id= #{appId}
     and d.server_id= #{serverId}
     and d.env_code= #{envCode}
     and d.deploy_type= #{deployType}
     and d.applicant like concat('%', #{applicant}, '%')

        and (
            d.applicant = #{scopeApplicant}
            or exists (
                select 1 from app leader_app
                inner join project leader_project on leader_project.id = leader_app.project_id and leader_project.deleted = 0
                where leader_app.deleted = 0 and leader_app.id = d.app_id
                and (
                    leader_project.leader = #{scopeApplicant}

                        or leader_project.leader = #{scopeLeader}

                )
            )
        )

     and s.env = #{scopeEnv}

        and d.status in

            #{scopeStatus}


     and d.approver like concat('%', #{approver}, '%')
     and d.apply_time >= #{startTime}
     and d.apply_time <= #{endTime}

order by d.id desc

mapper.update:
update deploy
set deleted = 1
where id = #{id}

update deploy
set status = #{status},
    row_version = row_version + 1

        , finish_time = null
        , finish_time = #{finishTime}

    , deploy_type = #{deployType}
where id = #{id}
  and deleted = 0
  and status = #{expectStatus}
  and row_version = #{rowVersion}

update deploy
set status = #{status},
    row_version = row_version + 1,
    approver = #{approver},
    approve_time = #{approveTime}
    , remark = #{remark}
where id = #{id}
  and deleted = 0
  and status = #{expectStatus}
  and row_version = #{rowVersion}

mapper.select:
select count(*)
from deploy
where deleted = 0
  and app_id = #{appId}
  and status = 'DEPLOYING'
  and id != #{excludeId}
  and env_code = #{envCode}

select version
from deploy
where deleted = 0
  and app_id = #{appId}
  and status = 'SUCCESS'
  and id != #{excludeId}
  and env_code = #{envCode}
order by finish_time desc, id desc
limit 1

select count(*)
from deploy
where deleted = 0
  and app_id = #{appId}
  and env_code = #{envCode}
  and status = 'SUCCESS'
  and (
    (ifnull(deploy_type, '') != 'ROLLBACK' and version = #{version})
    or (deploy_type = 'ROLLBACK' and rollback_version = #{version})
  )
